MATCH (fa:FlightAccident)-[:involves]->(am:AircraftModel {name:'Douglas DC-7'}),
      (fa)-[:departsFrom]->(airport:Airport {name:'Douala International Airport'})
RETURN DISTINCT fa.name AS accidentName;

MATCH (fa:FlightAccident)-[:involves]->(am:AircraftModel)
WHERE fa.name CONTAINS 'Pegasus Airlines Flight 2193' OR fa.flight_number = '2193'
RETURN am.name AS model_name, am.service_entry AS service_entry_date;

MATCH (f:FlightAccident)-[:involves]->(m:AircraftModel) 
WHERE f.name CONTAINS '2015 Juba' OR f.description CONTAINS '2015 Juba' 
RETURN m.name AS modelName, m.length_metre AS lengthInMeters;

// Find all FlightAccident names that either departed from Aeroparque Jorge Newbery
// or were destined for Ingeniero Aeronáutico Ambrosio L.V. Taravella International Airport

MATCH (fa:FlightAccident)-[:departsFrom]->(src:Airport)
WHERE src.name = "Aeroparque Jorge Newbery"
RETURN DISTINCT fa.name
UNION
MATCH (fa:FlightAccident)-[:destinedFor]->(dst:Airport)
WHERE dst.name = "Ingeniero Aeronáutico Ambrosio L.V. Taravella International Airport"
RETURN DISTINCT fa.name;

MATCH (fa:FlightAccident)
WHERE toLower(fa.name) CONTAINS 'flymontserrat' OR toLower(fa.flight_number) CONTAINS '107'
RETURN fa.location AS AccidentLocation;
